#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0 WITH LLVM-exception
"""Discriminating public-boundary controls generated by a portable recipe."""
import argparse
import datetime
import json
import os
from pathlib import Path
import subprocess
import sys

ROOT = Path(__file__).resolve().parents[2]
WORK = ROOT.parent/'codex/work/astra'
sys.path.insert(0,str(ROOT/'tests/selfhost-ownership-syntax-27b'))
from support import execute, output_path, sha, write


def cases():
	rows = []
	for count in (256,257):
		text = 'language astra27b;\n'
		text += ''.join('T identity_'+str(i)+'<T>(T value) { return value; }\n' for i in range(count))
		text += 'int main() {\n'+''.join('\tint value_'+str(i)+' = identity_'+str(i)+'<int>(42);\n' for i in range(count))+'\treturn value_'+str(count-1)+';\n}\n'
		rows.append(dict(id='generic-'+str(count),source=text,mode='native',exit=0 if count==256 else 1,diagnostic=None if count==256 else 'generic instance resource limit'))
	for count in (8,9):
		text = 'language astra27b;\nint main() { var plan = (0..1)'+''.join('.map(value => value+1)' for i in range(count))+'; if (plan.sum() != '+str(count)+') return 1; return 42; }\n'
		rows.append(dict(id='lazy-'+str(count),source=text,mode='native',exit=0 if count==8 else 1,diagnostic=None if count==8 else 'eight stages'))
		text = 'language astra27b;\nint main() {\n'+''.join('\tint capture_'+str(i)+' = 1;\n' for i in range(count))+'\tvar plan = (0..1).map(value => value'+''.join('+capture_'+str(i) for i in range(count))+');\n\tif (plan.sum() != '+str(count)+') return 1; return 42;\n}\n'
		rows.append(dict(id='captures-'+str(count),source=text,mode='native',exit=0 if count==8 else 1,diagnostic=None if count==8 else 'finite scalar/capture/effect subset'))
	for count in (1048576,1048577):
		text = 'language astra27b;\nint main() { var values = [for (var i in 0..'+str(count)+') => i]; if (len(values) != '+str(count)+' || values['+str(count-1)+'] != '+str(count-1)+') return 1; return 42; }\n'
		rows.append(dict(id='comprehension-'+str(count),source=text,mode='native',exit=0 if count==1048576 else 1,diagnostic=None if count==1048576 else 'proven count at most 1048576'))
	for count in (64,65):
		text = 'language astra27b;\nint main() { var plan = $"'+''.join('{'+str(i)+'}' for i in range(count))+'"; return 42; }\n'
		rows.append(dict(id='interpolation-'+str(count),source=text,mode='syntax',exit=0 if count==64 else 1,diagnostic=None if count==64 else 'at most 64 operands'))
	shared = (ROOT/'tests/books/shared.astra').read_text()
	legacy = shared.replace('language astra27b;','language legacy27a;')
	rows.append(dict(id='legacy-shared-explicit-borrow',source=legacy.replace('int shared_read(shared Reading','int shared_read(borrowed shared Reading'),mode='native',exit=0,diagnostic=None))
	rows.append(dict(id='legacy-shared-implicit-consume',source=legacy,mode='native',exit=1,diagnostic='Core verification failed'))
	return rows


def main():
	p = argparse.ArgumentParser(description=__doc__)
	for name in ('products','toolchain','build','runtime'): p.add_argument('--'+name,type=Path,required=True)
	p.add_argument('--quick',action='store_true')
	a = p.parse_args(); b = output_path(a.build,WORK/'build'); r = output_path(a.runtime,WORK/'runtime')
	b.mkdir(parents=True,exist_ok=False); r.mkdir(parents=True,exist_ok=False)
	(r/'executed-recipe.py.txt').write_bytes(Path(__file__).read_bytes())
	start = datetime.datetime.now(datetime.timezone.utc).isoformat()
	t = json.loads(a.toolchain.read_text()); assert all(sha(path)==digest for path,digest in t['tools'].items())
	products = json.loads(a.products.read_text())['products']
	for product in products.values():
		for image in (product,product['native'],product['doc']): assert sha(image['path'])==image['sha256']
	env = dict(os.environ,PYTHONDONTWRITEBYTECODE='1'); env.update({k:v for k,v in t['environment'].items() if v is not None}); env.pop('LD_PRELOAD',None); env.pop('VALGRIND_OPTS',None)
	assert subprocess.check_output(['llvm-config','--version'],env=env).strip()==b'23.1.4'
	rows = cases(); inputs = {}; commands = []; failures = []; emitted = {}
	for row in rows:
		source = r/(row['id']+'.astra'); source.write_text(row['source']); row['path'] = str(source); inputs[str(source)] = sha(source)
	write(r/'cases.json',rows)
	def run(label,argv,expected,memory=False):
		if memory: argv = ['valgrind','--trace-children=yes','--default-suppressions=no','--error-exitcode=99','--leak-check=full','--show-leak-kinds=all','--errors-for-leak-kinds=all',*argv]
		v = execute(argv,r/label,expected=expected,env=env,timeout=900)
		out = (r/label/'stdout').read_bytes(); err = (r/label/'stderr').read_bytes()
		commands.append(dict(label=label,argv=list(map(str,argv)),result=v,strict_memory=memory)); write(r/'commands.json',commands)
		if memory: assert all(marker in err for marker in (b'ERROR SUMMARY: 0 errors',b'in use at exit: 0 bytes in 0 blocks',b'(suppressed: 0 from 0)'))
		return v,out,err
	for row in rows:
		for host,product in products.items():
			for mode in (['syntax'] if row['mode']=='syntax' else ['check'] if a.quick else ['O0','O2']):
				label = row['id']+'-'+host+'-'+mode; obj = b/(label+'.o'); sentinel = b'LIMIT_REFUSAL_OUTPUT_SENTINEL\n'
				if mode in ('syntax','check'): argv = [product['path'],'--dump-syntax' if mode=='syntax' else '--check',row['path']]
				else:
					if row['exit']: obj.write_bytes(sentinel)
					argv = [product['path'],'-c','-'+mode,'-o',obj,row['path']]
				v,out,err = run(label,argv,row['exit'],memory=not a.quick)
				passed = v['status']=='EXPECTED_OUTCOME' and (not row['diagnostic'] or row['diagnostic'].encode() in err)
				if row['exit'] and mode=='syntax': passed = passed and out==b''
				if row['exit'] and mode in ('O0','O2'): passed = passed and obj.read_bytes()==sentinel
				if not passed: failures.append(dict(case=row['id'],label=label,result=v,diagnostic=err.decode(errors='replace')))
				if passed and not row['exit'] and mode in ('O0','O2'):
					exe = b/label
					v,_,_ = run(label+'-link',['cc','-no-pie',obj,'-o',exe],0); assert v['status']=='EXPECTED_OUTCOME'
					v,out,_ = run(label+'-execute',[exe],42,memory=True); assert v['status']=='EXPECTED_OUTCOME' and out==b''
					emitted[str(obj)] = sha(obj); emitted[str(exe)] = sha(exe)
		print(row['id'],'checked',flush=True)
	assert all(sha(path)==digest for path,digest in {**inputs,**emitted}.items())
	write(r/'result.json',dict(status=('BOUNDARY_PREFLIGHT_PASS' if a.quick else 'CURRENT_GENERIC_LAZY_CAPTURE_COMPREHENSION_AND_PARSER_BOUNDARIES_PASS') if not failures else 'BOUNDARY_FAILURE',start_UTC=start,completed_UTC=datetime.datetime.now(datetime.timezone.utc).isoformat(),cases_sha256=sha(r/'cases.json'),commands_sha256=sha(r/'commands.json'),inputs=inputs,emit_products=emitted,failures=failures,scope='Generated exact-boundary pairs, not an arbitrary program count. Native cases use actual host/target O0/O2, strict returning compiler/program memory and refusal sentinels; interpolation is explicitly parser-only. Quick mode grants no native credit. SSA 8M remains source-bound; no unrun 8M exhaustion claim.'))
	assert not failures


if __name__ == '__main__':
	main()
